### Python

```python
import sys


# 并查集，维护连通块大小
class DSU:
    def __init__(self, n):
        # parent[i] 表示节点 i 的父节点
        self.parent = list(range(n + 1))
        # size[i] 表示以 i 为根的集合大小
        self.size = [1] * (n + 1)
        # 当前最大的连通块大小，初始每个点单独成块，大小为 1
        self.max_size = 1

    # 查找根节点，带路径压缩
    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    # 合并两个集合，并更新最大连通块大小
    def union(self, x, y):
        rx = self.find(x)
        ry = self.find(y)

        if rx == ry:
            return

        # 按集合大小合并，小集合挂到大集合上
        if self.size[rx] < self.size[ry]:
            rx, ry = ry, rx

        self.parent[ry] = rx
        self.size[rx] += self.size[ry]

        if self.size[rx] > self.max_size:
            self.max_size = self.size[rx]


# 计算每个 k 对应的答案
def solve_one_case(n, arr):
    # edges 中保存 (边权, 左端点位置)
    # 表示位置 i 和 i+1 之间有一条边，边权为 abs(arr[i]-arr[i+1])
    edges = []
    for i in range(n - 1):
        diff = abs(arr[i] - arr[i + 1])
        edges.append((diff, i + 1))  # 使用 1-based 下标，连接 i+1 和 i+2

    # 按边权从小到大排序，方便随着 k 增加逐步加边
    edges.sort()

    dsu = DSU(n)
    ans = [1] * (n + 1)

    idx = 0
    m = len(edges)

    # 枚举 k=1..n
    for k in range(1, n + 1):
        # 将所有边权 <= k 的边加入图中
        while idx < m and edges[idx][0] <= k:
            pos = edges[idx][1]
            dsu.union(pos, pos + 1)
            idx += 1

        # 当前最大连通块大小就是答案
        ans[k] = dsu.max_size

    return ans[1:]


def main():
    input = sys.stdin.readline
    t = int(input().strip())
    out = []

    for _ in range(t):
        n = int(input().strip())
        arr = list(map(int, input().split()))
        res = solve_one_case(n, arr)
        out.append(" ".join(map(str, res)))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
```

