// 并查集，维护连通块大小
class DSU {
public:
    vector<int> parent;
    vector<int> sz;
    int maxSize;

    DSU(int n) {
        parent.resize(n + 1);
        sz.assign(n + 1, 1);

        for (int i = 1; i <= n; i++) {
            parent[i] = i;
        }

        // 初始每个点单独成块，最大大小为 1
        maxSize = 1;
    }

    // 查找根节点，带路径压缩
    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    // 合并两个集合，并更新最大连通块大小
    void unite(int x, int y) {
        int rx = find(x);
        int ry = find(y);

        if (rx == ry) {
            return;
        }

        // 按集合大小合并，小集合挂到大集合上
        if (sz[rx] < sz[ry]) {
            swap(rx, ry);
        }

        parent[ry] = rx;
        sz[rx] += sz[ry];

        if (sz[rx] > maxSize) {
            maxSize = sz[rx];
        }
    }
};

// 计算每个 k 对应的答案
vector<int> solveOneCase(int n, const vector<int>& arr) {
    vector<Edge> edges;

    // 构造相邻位置之间的边
    for (int i = 0; i < n - 1; i++) {
        int diff = abs(arr[i] - arr[i + 1]);
        edges.push_back({diff, i + 1});  // 连接位置 i+1 和 i+2
    }

    // 按边权从小到大排序
    sort(edges.begin(), edges.end());

    DSU dsu(n);
    vector<int> ans(n + 1, 1);
    int idx = 0;
    int m = (int)edges.size();

    // 枚举 k=1..n
    for (int k = 1; k <= n; k++) {
        // 将所有边权 <= k 的边加入图中
        while (idx < m && edges[idx].diff <= k) {
            int pos = edges[idx].pos;
            dsu.unite(pos, pos + 1);
            idx++;
        }

        // 当前最大连通块大小就是答案
