class DSU {
public:
    vector<int> parent;
    vector<int> sz;
    int maxSize;

    DSU(int n) {
        parent.resize(n + 1);
        sz.assign(n + 1, 1);
        for (int i = 1; i <= n; i++) {
            parent[i] = i;
        }
        maxSize = 1;
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void unite(int x, int y) {
        int rx = find(x);
        int ry = find(y);
        if (rx == ry) return;

        // 按大小合并，小集合挂到大集合上
        if (sz[rx] < sz[ry]) {
            swap(rx, ry);
        }
        parent[ry] = rx;
        sz[rx] += sz[ry];
        if (sz[rx] > maxSize) {
            maxSize = sz[rx];
        }
    }
};

vector<int> solveOneCase(int n, const vector<int>& arr) {
    vector<Edge> edges;
    for (int i = 0; i < n - 1; i++) {
        int diff = abs(arr[i] - arr[i + 1]);
        edges.push_back({diff, i + 1}); // 连接 i+1 和 i+2
    }

    sort(edges.begin(), edges.end());

    DSU dsu(n);
    vector<int> ans(n + 1);
